 dict(id='english',title='English & writing mentor',subject='English',stage='primary secondary',levels='Primary · Middle school · Secondary',portrait=1,tag='READING & EXPRESSION',intro='Build a clear idea, find the right words and develop a confident response.',focus=['Reading comprehension','Sentence and paragraph structure','Planning, drafting and improving writing'],approach='An example lesson combines discussion of a short passage with a focused writing task and feedback on one priority.',question='Is the main goal reading, writing, speaking or a particular school assessment?'),
 dict(id='science',title='Science learning mentor',subject='Science',stage='primary secondary',levels='Primary foundations · KS3 · GCSE / IGCSE discussion',portrait=2,tag='QUESTIONS & DISCOVERY',intro='Connect scientific ideas to everyday observations and careful explanations.',focus=['Core biology, chemistry and physics ideas','Diagrams, units and scientific vocabulary','Explaining observations and interpreting data'],approach='An example lesson moves from a familiar observation to a diagram, an explanation and a question that checks understanding.',question='Which science course, topic and type of question needs attention?'),
