def portrait(index,extra=''):
 return stock_image(PORTRAITS[index], 'Stock portrait for an example profile; not FCC staff', 'faculty-portrait '+extra, 900)


def example_card(t):
 details=''.join('<li>'+e(v)+'</li>' for v in t['focus'])
 href='/book-a-demo/?'+urlencode({'course':t.get('course',t['id']),'goal':f'Discuss a {t["subject"]} tutor match. Please confirm the tutor’s qualifications, relevant experience, teaching language and availability.'})
 search=' '.join([t['name'],t['title'],t['subject'],t['levels'],t['intro'],t['approach'],*t['focus']])
 profile=f'''<div class="faculty-modal-layout"><aside class="faculty-modal-sidebar"><div class="faculty-modal-portrait">{portrait(t['portrait'])}</div><span class="faculty-modal-example">Illustrative example profile</span><p>Example profile with a stock photograph, not an FCC staff biography.</p><div class="faculty-modal-stage"><span>Example learning focus</span><strong>{e(t['levels'])}</strong></div></aside><div class="faculty-modal-main"><span class="studio-label">{e(t['tag'])}</span><h2 id="faculty-profile-title">{e(t['name'])}</h2><p class="faculty-modal-role">{e(t['title'])}</p><p id="faculty-profile-summary" class="faculty-modal-intro">{e(t['intro'])}</p><section><h3>Subject areas to discuss</h3><ul>{details}</ul></section><section><h3>Illustrative lesson approach</h3><p>{e(t['approach'])}</p></section><dl class="faculty-modal-facts"><dt>Qualifications &amp; experience</dt><dd>To be confirmed in the approved tutor introduction.</dd><dt>Teaching language</dt><dd>Confirm the learner’s preferred language during matching.</dd><dt>Availability</dt><dd>Discuss local times, lesson length and tutor availability.</dd></dl><section class="faculty-modal-question"><h3>A useful first question</h3><p>{e(t['question'])}</p></section><a class="btn primary" href="{e(href,quote=True)}">Discuss this subject</a></div></div>'''
 return f'''<article class="faculty-card studio-reveal" data-faculty-card data-studio-card data-category="{e(t['subject'],quote=True)}" data-stages="{t['stage']}" data-profile-search="{e(search,quote=True)}"><div class="faculty-portrait-wrap">{portrait(t['portrait'])}<span class="faculty-example-badge">Example profile</span><span class="faculty-image-caption">Stock photo · not FCC staff</span></div><div class="faculty-copy"><span class="studio-label">{e(t['tag'])}</span><h3>{e(t['name'])}</h3><p class="faculty-role">{e(t['title'])}</p><div class="faculty-levels"><strong>{e(t['levels'])}</strong></div><button class="faculty-profile-open" type="button" data-profile-open="{e(t['id'],quote=True)}" aria-label="View profile details for {e(t['name'],quote=True)}" aria-haspopup="dialog" aria-controls="faculty-profile-dialog" hidden>View profile details<span aria-hidden="true">+</span></button><noscript><p class="faculty-profile-fallback">Enable JavaScript for the profile pop-up, or use the subject enquiry link below.</p></noscript><a class="btn secondary faculty-enquiry" href="{e(href,quote=True)}">Discuss this subject</a></div></article><template data-profile-template="{e(t['id'],quote=True)}">{profile}</template>'''


def profile_dialog():
 return '''<dialog id="faculty-profile-dialog" class="faculty-profile-dialog" data-faculty-dialog aria-labelledby="faculty-profile-title" aria-describedby="faculty-profile-summary"><div class="faculty-dialog-frame"><button type="button" class="faculty-dialog-close" data-profile-close aria-label="Close tutor profile" autofocus><span>Close</span><span aria-hidden="true">×</span></button><div class="faculty-dialog-scroll" data-profile-content></div></div></dialog>'''


def directory(button):
 if TUTORS:
  introduction='<div class="section-head"><span class="studio-label">TUTOR INTRODUCTIONS</span><h2>Meet your learning support.</h2><p>Discuss subject fit, learning goals and availability before agreeing on lessons.</p></div>'
  listing=tutor_cards()
 else:
  introduction='''<div class="faculty-intro"><span class="studio-label">EXPLORE THE PROFILE DIRECTORY</span><h2>Different subjects.<br><em>A personal approach.</em></h2><p>Use these examples to explore the kind of support to discuss for your child.</p></div><aside class="faculty-sample-notice"><strong>Illustrative tutor profiles</strong><p>These example profiles use stock photography and fictional names. They do not identify FCC staff. Confirm your matched tutor’s credentials and availability before choosing lessons.</p></aside>'''
  listing='''<div class="faculty-filter-bar" data-faculty-filters hidden><label>Find a subject or learning focus<input type="search" data-faculty-search placeholder="Try chemistry, writing or Qaida" autocomplete="off"></label><label>Learning stage<select data-faculty-stage><option value="">All stages</option><option value="primary">Primary foundations</option><option value="secondary">Secondary</option><option value="sixth-form">Sixth form / advanced discussion</option><option value="foundations">Quran foundations</option></select></label><button type="button" class="btn secondary" data-faculty-reset>Clear filters</button></div><p class="faculty-results" data-faculty-count role="status" aria-live="polite">12 illustrative profiles</p><div class="faculty-grid">'''+''.join(example_card(t) for t in EXAMPLES)+'''</div><div class="faculty-empty" data-faculty-empty hidden><h3>No profiles match this search.</h3><p>Try a different subject or select all learning stages.</p></div>'''+profile_dialog()
 return f'''<section class="faculty-page-hero"><div class="shell faculty-hero-grid"><div><span class="studio-label">TUTOR MATCHING AT FCC</span><h1>A good fit.<br><em>A better starting point.</em></h1><p>Start with the subject, the school course and the way your child learns. Explore example profiles, then discuss the right match.</p><div class="hero-actions">{button('Explore the profiles','#tutor-directory','light')}{button('Discuss a tutor match','/book-a-demo/','secondary')}</div></div><figure class="faculty-hero-art"><div class="faculty-hero-portraits">{portrait(0)}{portrait(1)}{portrait(4)}</div><figcaption>Example profiles · stock photography</figcaption><span aria-hidden="true" class="faculty-hero-star">✺</span></figure></div></section><section class="shell section faculty-directory" id="tutor-directory" data-faculty-directory>{introduction}{listing}</section><section class="faculty-match-band"><div class="shell section"><div class="section-head"><span class="studio-label">WHAT MAKES A GOOD MATCH?</span><h2>More than the subject name.</h2><p>Use the first conversation to make the practical details and learning approach clear.</p></div><div class="faculty-match-grid"><article><span aria-hidden="true">◎</span><h3>Course fit</h3><p>Share the subject, school year, curriculum and exam board. Ask about the tutor’s relevant experience and qualifications.</p></article><article><span aria-hidden="true">✺</span><h3>Learning fit</h3><p>Bring a recent question. Discuss pace, explanations, independent practice and how feedback will be shared.</p></article><article><span aria-hidden="true">◷</span><h3>Practical fit</h3><p>Confirm the teaching language, local lesson time, session length, platform, total fee and cancellation arrangements.</p></article></div></div></section><section class="shell section faculty-help"><div><span class="studio-label">NOT SURE WHERE TO BEGIN?</span><h2>Bring a question.<br>We’ll start there.</h2><p>A school topic, a recent piece of work or a clear goal can help shape the matching conversation.</p></div>{button('Start a demo enquiry','/book-a-demo/')}</section>'''

def teaser():
 return f'''<section class="shell section faculty-home-teaser"><div class="faculty-teaser-art" aria-label="Three stock photographs illustrating example tutor profiles"><div>{portrait(0)}</div><div>{portrait(2)}</div><div>{portrait(4)}</div><p>Stock photographs · not FCC staff</p></div><div class="faculty-teaser-copy"><span class="studio-label">THE CONNECTION BEHIND THE LESSON</span><h2>Good learning starts<br>with <em>a good fit.</em></h2><p>Explore subject-based example profiles, lesson approaches and the questions to ask before choosing a tutor.</p><div class="hero-actions"><a class="btn primary" href="/tutors/">Explore tutor profiles</a><a class="studio-inline-link" href="/about/">Get to know FCC</a></div></div></section>'''

def ceo_section():
 return '''<section class="campus-ceo-band" id="ceo-message" aria-labelledby="ceo-message-title"><div class="shell section campus-ceo-grid"><aside class="campus-ceo-identity"><figure class="campus-ceo-photo"><img class="" src="https://images.pexels.com/photos/20593094/pexels-photo-20593094.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=1000" alt="Books and a laptop on a study desk; editorial stock photograph" width="1000" height="750" loading="lazy" decoding="async" referrerpolicy="no-referrer"><figcaption>Learning inspiration · stock photograph</figcaption></figure><p class="campus-ceo-name">Khawaja Tahir Shafique</p><p class="campus-ceo-role">Chief Executive Officer<br>Future Cloud Campus</p></aside><div class="campus-ceo-message"><span class="studio-label">A MESSAGE FROM OUR CEO</span><h2 id="ceo-message-title">Every question deserves<br><em>a thoughtful response.</em></h2><span class="campus-ceo-draft">Draft message · prepared for approval</span><div class="campus-ceo-letter"><p>Every learner starts with a different question. At Future Cloud Campus, our aim is to make the next step clearer through patient explanations, purposeful practice and room to ask why.</p><p>Our vision brings academic learning, Quran Education and useful study resources into one thoughtful experience. We want progress to show in what a learner can explain, practise and try independently.</p><p>To parents and learners: keep sharing what matters, keep asking questions and take pride in the small breakthroughs. Thank you for being part of the future we are working to build.</p></div><div class="campus-ceo-signoff"><strong>Khawaja Tahir Shafique</strong><span>Chief Executive Officer, Future Cloud Campus</span></div></div></div></section>'''


def about_body(button):
 offers=[('mathematics','Academic tutoring','From foundations to exam preparation, start with the learner’s subject, school stage and current course.','/subjects/','Explore academic subjects'),('quran-education','Quran learning','Explore Noorani Qaida, Quran reading, Tajweed and introductory Islamic Studies, alongside Arabic text and Urdu translation.','/quran-education/','Open Quran Education'),('free-notes','Independent discovery','Use original topic guides, worked examples, short activities and study articles to keep asking questions between lessons.','/free-notes/','Visit the resource room')]
 offer_cards=''.join(f'<a class="campus-offer studio-reveal" href="{url}"><div class="campus-offer-image"><img src="/assets/pages/{image}.svg" alt="" width="480" height="360" loading="lazy"></div><div><h3>{title}</h3><p>{text}</p><span class="studio-inline-link">{label}</span></div></a>' for image,title,text,url,label in offers)
 values=[('Clarity','Explain an idea in manageable steps and check what the learner can do with it.'),('Patience','Make room for questions, mistakes and a pace suited to the learner.'),('Participation','Give the learner time to think, explain, practise and try independently.'),('Purpose','Connect the next activity to a specific learning goal and a useful next step.')]
 values_html=''.join(f'<article class="campus-value studio-reveal"><h3>{title}</h3><p>{text}</p></article>' for title,text in values)
 steps=[('Understand the starting point','Discuss the school course, recent work, goals and preferred lesson times.'),('Agree a suitable match','Confirm tutor credentials, relevant experience, approach and the practical arrangements.'),('Explain, practise and reflect','Use a focused lesson, guided examples and independent attempts to explore the topic.'),('Choose the next step','Review what is understood and agree a manageable focus for further practice.')]
 steps_html=''.join(f'<article><h3>{title}</h3><p>{text}</p></article>' for title,text in steps)
 return f'''<section class="shell section campus-story" id="campus-story"><span class="studio-label">WHAT FCC IS HERE TO DO</span><div><h2>One place for<br><em>many possibilities.</em></h2><p>Future Cloud Campus brings academic tutoring, Quran learning and self-study resources into one online campus experience. The focus is personal: understand where a learner is starting, make space for questions and keep the next step clear.</p><p>For families, that means a conversation about the actual school course, learning goals and day-to-day routine. For learners, it means being encouraged to take part, explain their thinking and build understanding through practice.</p></div></section><section class="campus-purpose-band"><div class="shell section campus-purpose-grid"><article class="studio-reveal"><span class="studio-label">OUR MISSION</span><h2>Make learning<br>feel more personal.</h2><p>Our aim is to make online learning clearer and more manageable through thoughtful guidance, patient explanations and purposeful practice.</p></article><article class="studio-reveal"><span class="studio-label">OUR VISION</span><h2>A campus that<br>keeps curiosity open.</h2><p>We want learners to see questions as a beginning, confidence as something they can build and education as a journey that extends beyond a single lesson.</p></article></div></section>{ceo_section()}<section class="shell section campus-offers"><div class="studio-section-top"><div><span class="studio-label">WHAT YOU CAN EXPLORE</span><h2>Your campus.<br><em>More than one path.</em></h2></div></div><div class="campus-offer-grid">{offer_cards}</div><div class="campus-library-facts"><div><strong>1:1</strong><span>The personal learning approach</span></div><div><strong>114</strong><span>Surahs in the Quran reader</span></div><div><strong>12</strong><span>Original downloadable study guides</span></div></div></section><section class="campus-values-band"><div class="shell section"><div class="section-head"><span class="studio-label">WHAT GUIDES THE EXPERIENCE</span><h2>Small habits.<br>Meaningful learning.</h2></div><div class="campus-values-grid">{values_html}</div></div></section><section class="shell section campus-method"><div class="section-head"><span class="studio-label">HOW THE APPROACH COMES TOGETHER</span><h2>A clear starting point.<br><em>A thoughtful next step.</em></h2></div><div class="campus-method-grid">{steps_html}</div></section><section class="campus-families-band"><div class="shell section campus-families-grid"><div><span class="studio-label">FOR LEARNERS & FAMILIES</span><h2>Make the learning<br>fit the learner.</h2><p>Discuss the school stage, curriculum, learning needs and time zone. Course fit should be based on the learner’s actual materials and goals.</p><div class="campus-path-links"><a href="/curricula/british/">British curriculum</a><a href="/curricula/american/">American school courses</a><a href="/curricula/ib/">IB pathways</a><a href="/curricula/pakistan/">Pakistan school courses</a></div><a class="btn secondary" href="/countries/">Explore country guidance</a></div><figure><img src="/assets/pages/parents.svg" width="480" height="360" alt="An illustrated learning progress conversation" loading="lazy"><figcaption>Learning goals, practical planning and family communication.</figcaption></figure></div></section>{teaser()}<section class="shell section campus-next"><div class="section-head"><span class="studio-label">STAY CONNECTED TO CAMPUS</span><h2>Explore what’s here.<br>See what comes next.</h2></div><div class="campus-next-grid"><a href="/try-a-lesson/"><span class="studio-label">TRY IT NOW</span><h3>A little learning, right here.</h3><p>Try a short maths or science activity without signing up.</p></a><a href="/progress/"><span class="studio-label">AN ILLUSTRATIVE GUIDE</span><h3>Make the next step visible.</h3><p>See how a sample progress note connects observations to practice.</p></a><a href="/portal/"><span class="studio-label">COMING SOON</span><h3>A connected portal experience.</h3><p>Explore the parent and teacher portal previews and their planned features.</p></a></div></section><section class="shell section campus-about-cta"><div><span class="studio-label">ONE CAMPUS. ENDLESS LEARNING.</span><h2>Start with curiosity.<br>Find your next step.</h2><p>Explore a subject, visit the library or start a demo enquiry with your learning goal.</p></div><div class="hero-actions">{button('Explore the subjects','/subjects/')}{button('Start a demo enquiry','/book-a-demo/','secondary')}</div></section>'''
